command:
if (!game.user.isGM) {
  ui.notifications.warn("Apenas o mestre pode resetar os handouts revelados.");
  return;
}

const NOME_JOURNAL_MUNDO = "Handouts Revelados";
const journalMundo = game.journal.getName(NOME_JOURNAL_MUNDO);

if (!journalMundo || !journalMundo.pages.size) {
  ui.notifications.info("Não há nenhum handout revelado pra resetar.");
  return;
}

const confirmado = await foundry.applications.api.DialogV2.confirm({
  window: { title: "Resetar Handouts Revelados" },
  content: `<p>Isso vai apagar os <strong>${journalMundo.pages.size}</strong> handout(s) já revelados aos jogadores do Journal "${NOME_JOURNAL_MUNDO}". Não dá pra desfazer.</p><p>Na próxima vez que você usar "Revelar Handout", todos vão aparecer como disponíveis de novo, como se nada tivesse sido mostrado ainda.</p>`,
  rejectClose: false
});
if (!confirmado) return;

const idsPaginas = journalMundo.pages.map((p) => p.id);
await journalMundo.deleteEmbeddedDocuments("JournalEntryPage", idsPaginas);

ui.notifications.info("Handouts revelados resetados! Todos voltaram a ficar disponíveis pra revelar de novo.");
